@import "@fontsource-variable/figtree";
@import "@fontsource-variable/spline-sans-mono";

/* Light (the faithful mode): a white page framed by two hairlines, cool slate-navy text,
   #f5f6f7 panels, a mint green for the main button, an electric lime for the badge and a
   bright sky blue as the second light. The developer band and the footer use the .dark
   values below (the blocks force them with the dark class). */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.268 0.03 248);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.268 0.03 248);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.268 0.03 248);
  --primary: oklch(0.862 0.168 170);
  --primary-foreground: oklch(0.268 0.03 248);
  --secondary: oklch(0.975 0.002 248);
  --secondary-foreground: oklch(0.268 0.03 248);
  --muted: oklch(0.975 0.002 248);
  --muted-foreground: oklch(0.549 0.025 245);
  --accent: oklch(0.954 0.005 248);
  --accent-foreground: oklch(0.268 0.03 248);
  --destructive: oklch(0.68 0.2 36);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.954 0.005 248);
  --input: oklch(0.894 0.013 245);
  --ring: oklch(0.69 0.17 243);
  --highlight: oklch(0.945 0.21 118);
  --highlight-foreground: oklch(0.268 0.03 248);
  --glow: oklch(0.69 0.17 243);
  --chart-1: oklch(0.862 0.168 170);
  --chart-2: oklch(0.69 0.17 243);
  --chart-3: oklch(0.945 0.21 118);
  --chart-4: oklch(0.79 0.14 205);
  --chart-5: oklch(0.68 0.2 36);
  --sidebar: oklch(0.975 0.002 248);
  --sidebar-foreground: oklch(0.268 0.03 248);
  --sidebar-primary: oklch(0.268 0.03 248);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.954 0.005 248);
  --sidebar-accent-foreground: oklch(0.268 0.03 248);
  --sidebar-border: oklch(0.954 0.005 248);
  --sidebar-ring: oklch(0.69 0.17 243);

  --typeface-body: "Figtree Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Figtree Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Spline Sans Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 72.5rem;
  --page-gutter: clamp(1rem, 2vw, 1.5rem);
  --section-y: clamp(4rem, 3rem + 3.5vw, 6.25rem);
}

/* Dark: the #151e29 navy of the developer band and footer, #1d2a36 raised boxes, white
   headings over a cool grey, the same mint, lime and blue. */
.dark {
  --background: oklch(0.228 0.024 252);
  --foreground: oklch(1 0 0);
  --card: oklch(0.268 0.024 248);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.268 0.024 248);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.862 0.168 170);
  --primary-foreground: oklch(0.215 0.022 252);
  --secondary: oklch(0.268 0.024 248);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.25 0.023 250);
  --muted-foreground: oklch(0.755 0.017 245);
  --accent: oklch(0.31 0.026 248);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.7 0.19 36);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 9%);
  --input: oklch(0.42 0.025 245);
  --ring: oklch(0.69 0.17 243);
  --highlight: oklch(0.945 0.21 118);
  --highlight-foreground: oklch(0.215 0.022 252);
  --glow: oklch(0.69 0.17 243);
  --chart-1: oklch(0.862 0.168 170);
  --chart-2: oklch(0.69 0.17 243);
  --chart-3: oklch(0.945 0.21 118);
  --chart-4: oklch(0.79 0.14 205);
  --chart-5: oklch(0.7 0.19 36);
  --sidebar: oklch(0.25 0.023 250);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.862 0.168 170);
  --sidebar-primary-foreground: oklch(0.215 0.022 252);
  --sidebar-accent: oklch(0.31 0.026 248);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 9%);
  --sidebar-ring: oklch(0.69 0.17 243);
}
